// Mails aller Konten einsammeln, Herkunft taggen und Prompt bauen.
// Die Quellenliste pflegt das Mail-Panel — der Bereich zwischen den Markern
// wird bei jedem Konto-Sync neu geschrieben.
const quellen = [
  ['gmail', 'Gmail Bestand'],
// PANEL:QUELLEN-START
// PANEL:QUELLEN-ENDE
];

function safeAll(name) {
  try { return $(name).all().filter(i => i.json && Object.keys(i.json).length > 0); }
  catch (e) { return []; }
}

// Gmail und der IMAP-Node liefern unterschiedliche Strukturen:
// Gmail    -> from / subject / snippet
// IMAP     -> envelope.from[].address / envelope.subject / textContent
function normalisieren(j, konto) {
  const e = j.envelope || {};
  const von = (e.from && e.from[0] && e.from[0].address)
    || (j.from && j.from.value && j.from.value[0] && j.from.value[0].address)
    || (j.from && j.from.text)
    || (typeof j.from === 'string' ? j.from : '')
    || '';
  const betreff = e.subject || j.subject || j.Subject || '(kein Betreff)';
  let text = j.textContent || j.textPlain || j.text || j.snippet || j.textHtml || '';
  if (typeof text !== 'string') text = JSON.stringify(text);
  text = text.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1500);

  const promptText = `Du bist ein E-Mail-Klassifizierer. Analysiere die folgende E-Mail und antworte NUR mit einem JSON-Objekt in exakt diesem Format:\n{"kategorie": "spam|rechnung|bestellung|newsletter|persoenlich|sonstiges", "spam_score": 0.0, "kurzfassung": "Ein Satz Zusammenfassung auf Deutsch"}\n\nRegeln:\n- spam_score: 0.0 (sicher kein Spam) bis 1.0 (sicher Spam). Phishing, Betrugsversuche, unserioese Werbung = hoher Score.\n- kategorie "rechnung": Rechnungen, Zahlungsaufforderungen, Kontoauszuege, Vertraege.\n- kategorie "bestellung": Bestell-/Versandbestaetigungen, Lieferstatus.\n- kategorie "newsletter": Newsletter und Marketing serioeser Absender.\n- kategorie "persoenlich": Mails von echten Menschen (privat oder geschaeftlich).\n- Alles andere: "sonstiges".\n\nE-Mail:\nVon: ${von}\nBetreff: ${betreff}\nText: ${text}`;

  return { konto, uid: j.uid ?? null, id: j.id ?? null, von, betreff, promptText };
}

const out = [];
for (const [konto, nodeName] of quellen) {
  for (const item of safeAll(nodeName)) {
    out.push({ json: normalisieren(item.json, konto) });
  }
}

if (out.length === 0) {
  return [{ json: { hinweis: 'Keine Mails im Bestand gefunden — nichts zu tun.' } }];
}
return out;

// Gemini-Antwort parsen und Zielordner bestimmen
const mail = $('Sammeln + Normalisieren').item.json;

let raw = '';
try { raw = $json.candidates[0].content.parts[0].text; } catch (e) { /* leer lassen */ }
raw = String(raw).replace(/```json|```/g, '').trim();

let k = { kategorie: 'sonstiges', spam_score: 0, kurzfassung: '' };
try { k = { ...k, ...JSON.parse(raw) }; } catch (e) { /* Fallback: sonstiges */ }

// >>> HIER die eigenen Gmail-Label-IDs eintragen (gleiche wie in Workflow 01) <<<
const GMAIL_LABELS = {
  Quarantaene: 'LABEL_ID_EINTRAGEN',
  Rechnungen: 'LABEL_ID_EINTRAGEN',
  Bestellungen: 'LABEL_ID_EINTRAGEN',
  Newsletter: 'LABEL_ID_EINTRAGEN',
};

let zielordner = null;
if (Number(k.spam_score) > 0.8) zielordner = 'Quarantaene';
else if (k.kategorie === 'rechnung') zielordner = 'Rechnungen';
else if (k.kategorie === 'bestellung') zielordner = 'Bestellungen';
else if (k.kategorie === 'newsletter') zielordner = 'Newsletter';

return {
  json: {
    ...mail,
    kategorie: k.kategorie,
    spam_score: Number(k.spam_score) || 0,
    kurzfassung: k.kurzfassung,
    zielordner,
    gmailLabelId: zielordner ? GMAIL_LABELS[zielordner] : null,
  },
};
